import React, { useEffect, useState } from 'react';
import axios from 'axios';
import SkillQuestionnaire from '/components/SkillQuestionnaire'; // Adjust path if needed

const Dashboard = () => {
  const [skills, setSkills] = useState([]);
  const [name, setName] = useState('');
  const [progress, setProgress] = useState(0);
  const [showQuestionnaire, setShowQuestionnaire] = useState(true);
  const [suggestions, setSuggestions] = useState('');
  const token = localStorage.getItem('token');

  const fetchSkills = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/skills', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSkills(res.data);
    } catch (err) {
      console.error('Failed to fetch skills:', err);
    }
  };

  useEffect(() => {
    if (!showQuestionnaire) {
      fetchSkills();
    }
  }, [showQuestionnaire]);

  const addSkill = async (e) => {
    e.preventDefault();
    if (!name) return;
    try {
      await axios.post('http://localhost:5000/api/skills', { name, progress }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setName('');
      setProgress(0);
      fetchSkills();
    } catch (err) {
      console.error('Failed to add skill:', err);
    }
  };

  const updateSkill = async (id, newProgress) => {
    try {
      const skillToUpdate = skills.find(s => s.id === id);
      if (!skillToUpdate) return;

      await axios.put(`http://localhost:5000/api/skills/${id}`, 
        { name: skillToUpdate.name, progress: newProgress }, 
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchSkills();
    } catch (err) {
      console.error('Failed to update skill:', err);
    }
  };

  const deleteSkill = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/skills/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchSkills();
    } catch (err) {
      console.error('Failed to delete skill:', err);
    }
  };

  const handleQuestionnaireSubmit = (suggestionText) => {
    setSuggestions(suggestionText);
    setShowQuestionnaire(false);
  };

  if (showQuestionnaire) {
    return (
      <SkillQuestionnaire token={token} onSubmit={handleQuestionnaireSubmit} />
    );
  }

  return (
    <div className="container">
      <h2 className="mb-4">AI Suggestions</h2>
      <pre style={{ whiteSpace: 'pre-wrap', backgroundColor: '#f8f9fa', padding: '1rem', borderRadius: '4px' }}>
        {suggestions || 'No suggestions yet.'}
      </pre>

      <h2 className="mt-5 mb-4">Your Skills</h2>
      <form onSubmit={addSkill} className="mb-3 d-flex gap-2">
        <input
          type="text"
          className="form-control"
          placeholder="Skill name"
          value={name}
          onChange={e => setName(e.target.value)}
          required
        />
        <input
          type="number"
          className="form-control"
          placeholder="Progress %"
          value={progress}
          onChange={e => setProgress(Number(e.target.value))}
          min="0"
          max="100"
        />
        <button type="submit" className="btn btn-success">Add Skill</button>
      </form>

      {Array.isArray(skills) && skills.length > 0 ? (
        <ul className="list-group">
          {skills.map(skill => (
            <li key={skill.id} className="list-group-item d-flex justify-content-between align-items-center">
              <div>
                <strong>{skill.name}</strong>
                <div className="progress mt-1" style={{ width: '200px' }}>
                  <div
                    className="progress-bar"
                    role="progressbar"
                    style={{ width: `${skill.progress}%` }}
                    aria-valuenow={skill.progress}
                    aria-valuemin="0"
                    aria-valuemax="100"
                  >
                    {skill.progress}%
                  </div>
                </div>
              </div>
              <div className="d-flex gap-2 align-items-center">
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={skill.progress}
                  onChange={e => updateSkill(skill.id, Number(e.target.value))}
                />
                <button
                  className="btn btn-danger btn-sm"
                  onClick={() => deleteSkill(skill.id)}
                >
                  Delete
                </button>
              </div>
            </li>
          ))}
        </ul>
      ) : (
        <p>No skills found. Add some to get started!</p>
      )}
    </div>
  );
};

export default Dashboard;
